// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public {
        c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this));
    }
    function testFuzz_property(uint128 price, address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.updatePrice(price) {} catch {}
        assertEq(c.lastPriceUpdate(), 0);
    }
}
